def toposort(graph):
    import heapq
    nodes=set(graph)|{v for vs in graph.values() for v in vs}
    deg={n:0 for n in nodes}
    for vs in graph.values():
        for v in set(vs): deg[v]+=1
    q=[n for n in nodes if deg[n]==0]; heapq.heapify(q); out=[]
    while q:
        n=heapq.heappop(q); out.append(n)
        for v in set(graph.get(n,[])):
            deg[v]-=1
            if deg[v]==0: heapq.heappush(q,v)
    if len(out)!=len(nodes): raise ValueError('cycle')
    return out

