import unittest
from solution import toposort

class ContractTests(unittest.TestCase):
    def test_00(self):
        self.assertEqual(toposort({'b':['c'],'a':['c']}), ['a','b','c'])
    def test_01(self):
        with self.assertRaises(ValueError): toposort({'a':['b'],'b':['a']})
    def test_02(self):
        self.assertEqual(toposort({'a':['b','b']}), ['a','b'])
    def test_03(self):
        self.assertEqual(toposort({}), [])

